{"code": "import os

# Check if there's another data directory
print("All directories in current location:")
for item in os.listdir('.'):
    if os.path.isdir(item):
        print(f"  {item}/")

# Check if there's a 'data' parent directory
print("\nChecking for data directories...")
for root, dirs, files in os.walk('.'):
    # Look for directories that might contain images
    for d in dirs:
        if 'image' in d.lower() or 'img' in d.lower() or 'train' in d.lower():
            full_path = os.path.join(root, d)
            files_in_dir = os.listdir(full_path) if os.path.isdir(full_path) else []
            print(f"\nFound potential image dir: {full_path}")
            print(f"  Contains {len(files_in_dir)} items")"}

